// src/Features/ApplicantsSlice.js

import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import axios from "axios";
import * as ENV from "../config";

// Fetch applicants for a job
export const fetchApplicants = createAsyncThunk(
  "applicants/fetchApplicants",
  async (jobId, thunkAPI) => {
    try {
      const res = await axios.get(
        `${ENV.SERVER_URL}/company/applicants/${jobId}`
      );
      return res.data;
    } catch (err) {
      return thunkAPI.rejectWithValue(
        err.response?.data || "Failed to load applicants"
      );
    }
  }
);

// Update status (Accept / Reject)
export const updateApplicantStatus = createAsyncThunk(
  "applicants/updateStatus",
  async ({ applicationId, status }, thunkAPI) => {
    try {
      const res = await axios.put(
        `${ENV.SERVER_URL}/company/applications/status/${applicationId}`,
        { status }
      );
      return res.data;
    } catch (err) {
      return thunkAPI.rejectWithValue(err.response?.data || "Update failed");
    }
  }
);

const applicantsSlice = createSlice({
  name: "applicants",
  initialState: {
    list: [],
    isLoading: false,
    isError: false,
  },

  extraReducers: (builder) => {
    builder
      .addCase(fetchApplicants.pending, (state) => {
        state.isLoading = true;
      })
      .addCase(fetchApplicants.fulfilled, (state, action) => {
        state.isLoading = false;
        state.list = action.payload;
      })
      .addCase(fetchApplicants.rejected, (state) => {
        state.isLoading = false;
        state.isError = true;
      })
      .addCase(updateApplicantStatus.fulfilled, (state, action) => {
        const updated = action.payload;
        const index = state.list.findIndex((x) => x._id === updated._id);
        if (index !== -1) {
          state.list[index].status = updated.status;
        }
      });
  },
});

export default applicantsSlice.reducer;
